"The Nagging React newbie" JUSPAY CODING HACKATHON QUESTION
The Nagging React newbie

A Nagging React newbie "B" is constantly troubling React expert "A". React Expert "A"

needs to know the minimum set of people following him he needs to remove from his

network to stop "B" from reaching out to him.

INPUT FORMAT

Total Members in IJI Friend Network = N

Memberldl = NI

Memberld2 = N2

Memberld3 = N3

MemberldN = Nn

Total Possible Edges = E

<Follower 1> <Following 1>

<FolIower <Following

<FolIower <Following

Follower = A

Following = B

OUTPUT FORMAT

Set of memberld "A" needs to block

OUTPUT FORMAT

Set of memberld "A" needs to block

Sample Input

4

2

5

7

9

4

29

72

79

95

7

9

Sample Output

27

Disclaimer: The solution file for this question is not updated and hence, you cannot use

custom input and output option for this question.

SOLUTION

```
#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> graph;
vector<bool> visited; 
vector<bool> dirty;

void dfs(int node, int parent) {
  visited[node] = true;

  for(int child : graph[node]) {
    if(!visited[child]) {
      dfs(child, node);
    }
  }

  if(parent != -1) {
    dirty[parent] = dirty[parent] | dirty[node]; 
  }
}

int main() {

  int n;
  cin >> n;

  int sz = 0;
  for(int i = 0; i<n; i++) {
    int node;
    cin >> node;
    sz = max(sz, node+1);
  }

  int edges;
  cin >> edges;

  graph.resize(sz);
  visited.resize(sz, false);
  dirty.resize(sz, false);

  for(int i = 0; i<edges; i++) {
    int u, v;
    cin >> u >> v;
    graph[v].push_back(u);
  }

  int enemy, person;
  cin >> enemy >> person;

  dirty[enemy] = true;

  dfs(person, -1);

  for(int child : graph[person]) {
    if(dirty[child]) {
      cout << child << " ";
    }
  }

  return 0;
}
```
